const bars = Array.from({ length: 600 }, (_, i) => ({
  time: 1700000040000 + i * 120000,
  open: 1,
  high: 2,
  low: 0,
  close: 1,
  volume: 1,
}));

// Exact v21 source/CSV bindings; asserted index/count/serial cells are independent of OHLCV.
describe('native v21 quota50 and quota500 cadence', () => {
  it.each(captures)('$name [$csvSha256]', (capture) => {
    expect(createHash('sha256').update(capture.source).digest('hex')).toBe(capture.sourceSha256);
    const result = executeScript(parse(capture.source), bars, undefined, {
      runtime: { timeframe: { period: '2', multiplier: 2, isminutes: true, isintraday: true } },
    });
    expect(result.errors).toEqual([]);
    expect(result.profile.swallowedErrors ?? []).toEqual([]);
    for (const [title, expected] of Object.entries(capture.expected)) {
      const plot = result.plots.find((p) => p.title === title);
      expect(plot, title).toBeDefined();
      expect(
        capture.indices.map((index) => plot?.values[index]),
        title,
      ).toEqual(expected);
    }
  });
});
